# WAR ARENA - GMGN CLI Executor - Windows shim fix
# Fixes: execFile could not resolve gmgn-cli (.cmd shim) on Windows -> ENOENT.
# Now uses shell resolution on Windows only. Run from project root:
#   powershell -ExecutionPolicy Bypass -File .\fix-gmgn-windows.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - GMGN CLI Windows shim fix" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/integration/GmgnCliExecutor.ts" ""
Write-B64 "tests/unit/gmgnCliExecutor.test.ts" ""

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "Fix applied. Expected: 865 passed + 1 skipped." -ForegroundColor Green
Write-Host "Now re-run: `$env:GMGN_API_KEY=...; powershell -ExecutionPolicy Bypass -File .\verify-gmgn-live.ps1" -ForegroundColor Yellow
